# game.py
from flask import Flask, render_template, request

app = Flask(__name__)

def start_game():
    return render_template("index.html")

@app.route("/", methods=["GET", "POST"])
def index():
    if request.method == "POST":
        choice = request.form.get("choice").lower()

        if choice == "left":
            return render_template("result.html", message="You encounter a friendly goblin who gives you a map. The map shows a hidden treasure room! Congratulations! You found the treasure!")
        elif choice == "right":
            return render_template("result.html", message="You fall into a pit and get eaten by a giant spider. Game Over!")
        else:
            return render_template("result.html", message="Invalid choice. Game Over!")
    return render_template("index.html")

if __name__ == "__main__":
    app.run(debug=True)
```

